#[test]
fn cdl_matches_pyocio() {
    let mut worst = 0.0f32;
    for &(name, clamp, inverse, slope, offset, power, sat, input, want) in ORACLE {
        let mut got = input;
        match (clamp, inverse) {
            (true, false) => apply_cdl_clamped(&mut got, slope, offset, power, sat),
            (false, false) => apply_cdl_unclamped(&mut got, slope, offset, power, sat),
            (true, true) => apply_cdl_inverse_clamped(&mut got, slope, offset, power, sat),
            (false, true) => apply_cdl_inverse_unclamped(&mut got, slope, offset, power, sat),
        }
        // Deliberate divergence: OCIO's optimizer turns a power-(1,1,1) `CDL_V1_2_REV` into
        // matrices and drops the final `[0, 1]` clamp (PyOpenColorIO returns -0.0167 and 1.122
        // for the clamped style), while its own renderer path and the ASC v1.2 spec clamp. We
        // keep the clamp, so here we must equal OCIO's value clamped.
        let want = if clamp && inverse && power == [1.0; 3] {
            want.map(|v| v.clamp(0.0, 1.0))
        } else {
            want
        };
        for c in 0..3 {
            if want[c].is_infinite() {
                assert_eq!(
                    got[c], want[c],
                    "{name} {input:?}: got {got:?}, OCIO {want:?}"
                );
                continue;
            }
            let err = (got[c] - want[c]).abs() / want[c].abs().max(1.0);
            worst = worst.max(err);
            // A few f32 ulps: the matrix path (power 1) rounds its saturation matrix differently.
            assert!(
                err <= 4.0 * f32::EPSILON,
                "{name} clamp={clamp} inverse={inverse} {input:?}: got {got:?}, OCIO {want:?}"
            );
        }
    }
    eprintln!("cdl_matches_pyocio: worst relative error {worst:.3e}");
}
